// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 newMtFeeRate) public {
        newMtFeeRate = bound(newMtFeeRate, 0, 1e18);

        // Record BASE_RESERVE_ before the call
        uint256 baseReserveBefore = uint256(c._BASE_RESERVE_());

        // Call adjustMtFeeRate
        c.adjustMtFeeRate(newMtFeeRate);

        // Assert: _BASE_RESERVE_ unchanged
        assertTrue(c._BASE_RESERVE_() == baseReserveBefore);
    }
