// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        // Restrict mtFeeRate to a valid range
        mtFeeRate = bound(mtFeeRate, 0, 1e18);

        // Record pre-call _BASE_RESERVE_
        uint256 preBaseReserve = c._BASE_RESERVE_();

        // Call adjustMtFeeRate - only maintainer can call, prank as maintainer
        // The maintainer is not set initially, so we need to set it
        // But we can't set _MAINTAINER_ directly, so we'll use the contract's own address
        // Actually the maintainer is address(0) by default, so only address(0) can call
        // We'll deploy a simpler approach: just call without prank since the test may revert
        // For the property to hold on C, we need the call to succeed
        // Since msg.sender is address(this) and _MAINTAINER_ is address(0), we need to prank as address(0)
        vm.prank(address(0));
        // The function may revert if not maintainer, so we use try/catch
        // But for the property we check state only if call succeeds
        (bool success,) = address(c).call(abi.encodeWithSelector(c.adjustMtFeeRate.selector, mtFeeRate));

        // If the call succeeded, the _BASE_RESERVE_ should be unchanged
        if (success) {
            uint256 postBaseReserve = c._BASE_RESERVE_();
            assertTrue(preBaseReserve == postBaseReserve, "BASE_RESERVE_ changed after adjustMtFeeRate");
        } else {
            // If call reverted, we still check that the state is unchanged
            uint256 postBaseReserve = c._BASE_RESERVE_();
            assertTrue(preBaseReserve == postBaseReserve, "BASE_RESERVE_ changed after revert");
        }
    }
}

