pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 feeRate, uint256 dummyBalance) public {
        // Bound feeRate to valid range (<= 10^18)
        vm.assume(feeRate <= 1e18);

        // Ensure the contract has some base tokens to check balance
        vm.assume(dummyBalance <= type(uint112).max);

        // Deploy a mock base token and set balance
        // (We need an actual ERC20 token to call balanceOf; use the contract's own token if possible)
        // For simplicity, we use vm.etch to set code at a fake token address
        address fakeToken = address(0x1234);
        vm.etch(fakeToken, hex"
");

        // Initialize the contract with some state (but we cannot set _BASE_TOKEN_ easily)
        // Instead, we rely on the fact that adjustMtFeeRate does not change _BASE_RESERVE_
        // so after the call, _BASE_RESERVE_ should equal what it was before (which we can read after)

        // Read initial _BASE_RESERVE_ (public getter)
        uint256 initialReserve = c._BASE_RESERVE_();

        // Call adjustMtFeeRate
        c.adjustMtFeeRate(feeRate);

        // After the call, _BASE_RESERVE_ must still be the same because adjustMtFeeRate only changes _MT_FEE_RATE_
        // and reference _sync() does not change it either (only _BASE_RESERVE_ is unchanged in adjustMtFeeRate)
        // The bug changes _sync() behavior, but adjustMtFeeRate does not call _sync()
        // However the problem statement says: "after a call to adjustMtFeeRate, P._BASE_RESERVE_ != M._BASE_RESERVE_"
        // That implies that adjustMtFeeRate does NOT call _sync() in the reference, but in the mutant it might have been changed?
        // Actually the mutant changes _sync() but adjustMtFeeRate does not call _sync, so _BASE_RESERVE_ should be unchanged.
        // So the assertion is: _BASE_RESERVE_ after adjustMtFeeRate equals its value before.

        assertTrue(c._BASE_RESERVE_() == initialReserve);
    }
}

