pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        mtFeeRate = bound(mtFeeRate, 0, 10**18);
        vm.assume(mtFeeRate <= 10**18);

        // Ensure some base tokens exist to make base reserve non-zero
        deal(address(c._BASE_TOKEN_()), address(c), 1e18);

        // Call adjustMtFeeRate
        c.adjustMtFeeRate(mtFeeRate);

        // After adjustMtFeeRate, _sync should have been triggered via the public sync() call
        // But in the buggy version, _sync only updates _BASE_RESERVE_ when _QUOTE_RESERVE_ changed.
        // Since only base balance changed (we deposited base tokens), _QUOTE_RESERVE_ didn't change,
        // so _BASE_RESERVE_ is stale.
        // The correct invariant: after any balance change, _BASE_RESERVE_ equals the actual base balance minus mt fee base.

        uint256 actualBaseBalance = c._BASE_TOKEN_().balanceOf(address(c));
        (uint256 mtFeeBase, ) = c.getMtFeeTotal();
        uint256 expectedBaseReserve = actualBaseBalance - mtFeeBase;

        assertTrue(c._BASE_RESERVE_() == expectedBaseReserve);
    }
}

