pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        vm.assume(mtFeeRate <= 1e18);

        // Get balances before
        (uint256 baseReserveBefore, ) = c.getVaultReserve();
        uint256 baseInputBefore = c.getBaseInput();

        c.adjustMtFeeRate(mtFeeRate);

        // Get balances after
        (uint256 baseReserveAfter, ) = c.getVaultReserve();
        uint256 baseInputAfter = c.getBaseInput();

        // The change in base reserve should exactly equal the change in base input
        // because baseInput = actualBalance - baseReserve - mtFeeBase, and mtFeeBase is unchanged
        // So (actualBalance - baseReserve) difference = baseInput difference
        // Therefore: baseReserveAfter - baseReserveBefore == baseInputBefore - baseInputAfter
        bool ok = (int(baseReserveAfter) - int(baseReserveBefore)) == (int(baseInputBefore) - int(baseInputAfter));
        assertTrue(ok);
    }
}

