    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        mtFeeRate = bound(mtFeeRate, 0, 1e18);

        // Apply some state changes to trigger _setReserve
        // We need to call a function that eventually calls _setReserve
        // adjustMtFeeRate doesn't call _setReserve directly, but we can
        // simulate by first calling buyShares to set reserves
        // Then call adjustMtFeeRate

        // First, ensure there are reserves by buying shares
        // We'll assume base token has been sent to the contract

        c.adjustMtFeeRate(mtFeeRate);

        // The invariant: after any call to adjustMtFeeRate,
