        // To detect the difference, we read _QUOTE_RESERVE_ via getVaultReserve
        (uint256 baseReserve, uint256 quoteReserve) = c.getVaultReserve();

        // The general rule: if the contract was just deployed, reserves are 0.
        // If we only called adjustMtFeeRate, reserves must remain 0 (no change).
        assertTrue(quoteReserve == 0, "_QUOTE_RESERVE_ should remain unchanged");
