        // Slot 1: _IS_OPEN_TWAP_ (bool)
        // Slot 2: _MAINTAINER_ (address)
        // Slot 3: _BASE_TOKEN_ (address)
        // Slot 4: _QUOTE_TOKEN_ (address)
        // Slot 5: _BASE_RESERVE_ (uint112) + _QUOTE_RESERVE_ (uint112) packed
        // We'll set both in one slot: baseReserve in lower 112 bits, quoteReserve in next 112 bits
        // We want _RState_ = BELOW_ONE = 2 (PMMPricing.RState.BELOW_ONE)
        // Put _RState_ in slot 10 (uint32)
        // _BASE_TARGET_ in slot 8, _QUOTE_TARGET_ in slot 9 (both uint112)
        // We'll set baseTarget = baseReserve (equality to trigger bug), quoteTarget = quoteReserve
        // RState = BELOW_ONE (2)
        // First, ensure _BASE_TOKEN_ and _QUOTE_TOKEN_ are set to some dummy ERC20? No, we just need the slot values; the contract functions may fail if tokens not set but adjustMtFeeRate doesn't need them.
        // We'll set a dummy address for tokens to avoid revert in other areas? adjustMtFeeRate only changes _MT_FEE_RATE_, it doesn't call token.
        // Set _MAINTAINER_ to address(this) for prank
        vm.store(address(c), bytes32(uint256(2)), bytes32(uint256(uint160(address(this)))));
        // Set _BASE_TOKEN_ and _QUOTE_TOKEN_ dummy
        vm.store(address(c), bytes32(uint256(3)), bytes32(uint256(uint160(address(0x1)))));
        vm.store(address(c), bytes32(uint256(4)), bytes32(uint256(uint160(address(0x2)))));
        // Set _BASE_RESERVE_ and _QUOTE_RESERVE_
        vm.store(address(c), bytes32(uint256(5)), bytes32(uint256(baseReserve) | (uint256(quoteReserve) << 112)));
        // Set _BASE_TARGET_ = baseReserve (equality)
        vm.store(address(c), bytes32(uint256(8)), bytes32(uint256(baseReserve)));
        // Set _QUOTE_TARGET_ = quoteReserve
        vm.store(address(c), bytes32(uint256(9)), bytes32(uint256(quoteReserve)));
        // Set _RState_ = 2 (BELOW_ONE)
        vm.store(address(c), bytes32(uint256(10)), bytes32(uint256(2)));

        // Record _QUOTE_TARGET_ before
        uint256 quoteTargetBefore = c._QUOTE_TARGET_();

        // Call adjustMtFeeRate (onlyMaintainer, we are maintainer)
        c.adjustMtFeeRate(mtFeeRate);

        // Record _QUOTE_TARGET_ after (should not change if bug is absent)
        uint256 quoteTargetAfter = c._QUOTE_TARGET_();

        // Property: quote target remains same after adjustMtFeeRate
        assertTrue(quoteTargetBefore == quoteTargetAfter, "_QUOTE_TARGET_ changed after adjustMtFeeRate");
    }
}

