import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint256 baseReserve,
        uint256 quoteReserve,
        uint256 baseTarget,
        uint256 quoteTarget,
        uint256 mtFeeRate
    ) public {
        // Bound inputs to avoid overflow, ensure values fit in uint112 and are valid
        vm.assume(baseReserve > 0 && baseReserve <= type(uint112).max);
        vm.assume(quoteReserve > 0 && quoteReserve <= type(uint112).max);
        vm.assume(baseTarget > 0 && baseTarget <= type(uint112).max);
        vm.assume(quoteTarget > 0 && quoteTarget <= type(uint112).max);
        vm.assume(mtFeeRate <= 1e18);

        // Ensure the state is BELOW_ONE: base reserve equals base target exactly
        vm.assume(baseReserve == baseTarget);
        // For BELOW_ONE, quote reserve should be less than quote target (since RState BELOW_ONE means quote is sold below target)
        vm.assume(quoteReserve < quoteTarget);

        // Set state variables directly using vm.store to set initial conditions
        // We need to set _BASE_RESERVE_, _QUOTE_RESERVE_, _BASE_TARGET_, _QUOTE_TARGET_, _RState_
        // Using slot layout from GSPStorage
        // _BASE_RESERVE_ (uint112) slot 5 (0-indexed)
        vm.store(address(c), bytes32(uint256(5)), bytes32(uint256(baseReserve)));
        // _QUOTE_RESERVE_ (uint112, packed with _BLOCK_TIMESTAMP_LAST_ in slot 6, but we set only low 112 bits)
        // Actually slot 6 contains _QUOTE_RESERVE_ (112 bits) and _BLOCK_TIMESTAMP_LAST_ (32 bits). We set just quote reserve.
        bytes32 slot6 = vm.load(address(c), bytes32(uint256(6)));
        slot6 = (slot6 & ~bytes32(uint256(type(uint112).max))) | bytes32(uint256(quoteReserve));
        vm.store(address(c), bytes32(uint256(6)), slot6);
        // _BASE_TARGET_ slot 8
        vm.store(address(c), bytes32(uint256(8)), bytes32(uint256(baseTarget)));
        // _QUOTE_TARGET_ slot 9
        vm.store(address(c), bytes32(uint256(9)), bytes32(uint256(quoteTarget)));
        // _RState_ slot 10 (uint32)
        vm.store(address(c), bytes32(uint256(10)), bytes32(uint256(uint32(PMMPricing.RState.BELOW_ONE))));

        // Record _QUOTE_TARGET_ before
        uint256 quoteTargetBefore = uint256(vm.load(address(c), bytes32(uint256(9))));

        // Call adjustMtFeeRate (this is the entry that triggers the bug via correctRState internally? 
        // Actually correctRState is not called automatically; but the bug manifests after a call to any function that triggers internal logic.
        // The difference says: after a call to adjustMtFeeRate, the value of _QUOTE_TARGET_ differs between P and M.
        // However correctRState must be called to see the difference. We'll call correctRState explicitly after adjustMtFeeRate.
        c.adjustMtFeeRate(mtFeeRate);

        // Now call correctRState which uses the condition with <= in mutant
        c.correctRState();

        // Read _QUOTE_TARGET_ after
        uint256 quoteTargetAfter = uint256(vm.load(address(c), bytes32(uint256(9))));

        // In reference C, since baseReserve == baseTarget, condition _BASE_RESERVE_ < _BASE_TARGET_ is false, so no change.
        // In mutant, condition _BASE_RESERVE_ <= _BASE_TARGET_ is true, so _QUOTE_TARGET_ gets reset to _QUOTE_RESERVE_.
        // Thus the rule: _QUOTE_TARGET_ should remain unchanged.
        // But the mutant breaks this rule, so asserting that it remains the same will pass on reference and fail on mutant.
        assertTrue(quoteTargetAfter == quoteTargetBefore, "_QUOTE_TARGET_ changed after correctRState when baseReserve == baseTarget");
    }
}

